            }
        }
        // Fallback: any audio class interface
        for (i in 0 until device.interfaceCount) {
            val iface = device.getInterface(i)
            if (iface.interfaceClass == UsbConstants.USB_CLASS_AUDIO) {
                return iface
            }
        }
        return null
    }

    private fun extractDeviceInfo(device: UsbDevice): UsbDeviceInfo {
        val vendor = usbManager.getVendorName(device) ?: "Unknown"
        val product = usbManager.getProductName(device) ?: device.deviceName
