            name = device.deviceName,
            vendor = vendor,
            product = product,
            sampleRates = listOf(44100, 48000, 96000),
            channels = 2
        )
    }

    private fun detectCapabilities(
        device: UsbDevice,
        connection: UsbDeviceConnection,
        iface: UsbInterface
    ) {
