    fun startNoiseCapture() {
        if (!_uiState.value.isRunning) return
        engine?.startNoiseCapture()
        _uiState.update {
            it.copy(
                isNoiseCapturing = true,
                noiseCaptureProgress = 0f,
                hasNoiseProfile = false
