                activeProfile = profile
            )
        }
    }

    fun loadProfile(profile: RoomProfile) {
        val bands = _uiState.value.bands.toMutableList()
        for (i in bands.indices) {
            if (i < profile.measuredGains.size) {
                bands[i] = bands[i].copy(
