        }
    }

    fun setPushGainsEnabled(enabled: Boolean) {
        _uiState.update {
            it.copy(consoleConfig = it.consoleConfig.copy(pushGainsToConsole = enabled))
        }
    }

    fun setPullGainsEnabled(enabled: Boolean) {
