                    }
                }
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        engine?.stop()
        engine = null
        consoleManager?.disconnect()
        consoleManager = null
        meshManager?.stop()
        meshManager = null
        usbAudioSource?.disconnect()
        usbAudioSource = null
    }
